package meteordevelopment.meteorclient.systems.modules;
import java.util.*;
public class Modules {private static final Modules INSTANCE=new Modules();public static final List<Category> categories=new ArrayList<>();public static final Map<Category,List<Module>> data=new LinkedHashMap<>();public static Modules get(){return INSTANCE;}public static Iterable<Category> loopCategories(){return categories;}public List<Module> getGroup(Category c){return data.getOrDefault(c,List.of());}public Collection<Module> getAll(){List<Module> all=new ArrayList<>();data.values().forEach(all::addAll);return all;}public static void setup(int n,int rows){categories.clear();data.clear();String[] names={"Combat","Player","Movement","Render","World","Misc","Satellite","Meteorist","Addon without icon","Addon with a very long category name"};for(int i=0;i<n;i++){Category c=new Category(i<names.length?names[i]:"Addon "+i);categories.add(c);List<Module> m=new ArrayList<>();String[] moduleNames={"Better Tooltips","Inventory Tweaks","Camera Tweaks","Block Selection","Custom Module With A Long Descriptive Name","Sound Options","Display Settings","Interface Preferences"};for(int j=0;j<rows;j++){Module item=new Module(c,j<moduleNames.length?(i==0?moduleNames[j]:moduleNames[j]+" "+i):"Module "+i+"-"+j);item.favorite=j%6==0;item.active=j%5==0;m.add(item);}data.put(c,m);}}}
